"""
Python SDK Example - Using the generated SDK

This example shows how to use the auto-generated Python SDK.
"""

# After generating the SDK, you would import it like:
# from mcp_gateway_sdk import MCPGatewayClient

# For demonstration, here's how it would be used:

class MCPGatewayClient:
    """Example SDK client (generated by gateway)."""
    
    def __init__(self, api_key: str, base_url: str = "http://localhost:8000"):
        self.api_key = api_key
        self.base_url = base_url
        self.headers = {
            "X-API-Key": api_key,
            "Content-Type": "application/json"
        }
    
    def mcp_query(self, query: str, context: dict = None):
        """Send MCP query."""
        import requests
        data = {"query": query}
        if context:
            data["context"] = context
        
        response = requests.post(
            f"{self.base_url}/mcp/query",
            json=data,
            headers=self.headers
        )
        response.raise_for_status()
        return response.json()
    
    def a2a_send_message(self, message: str, target_agent: str):
        """Send A2A message."""
        import requests
        data = {
            "message": message,
            "target_agent": target_agent
        }
        
        response = requests.post(
            f"{self.base_url}/a2a/message",
            json=data,
            headers=self.headers
        )
        response.raise_for_status()
        return response.json()
    
    def mqtt_publish(self, topic: str, payload: dict, qos: int = 1):
        """Publish MQTT message."""
        import requests
        data = {
            "topic": topic,
            "payload": payload,
            "qos": qos
        }
        
        response = requests.post(
            f"{self.base_url}/mqtt/publish",
            json=data,
            headers=self.headers
        )
        response.raise_for_status()
        return response.json()


# Example usage:
if __name__ == "__main__":
    # Initialize client
    client = MCPGatewayClient(api_key="your-api-key")
    
    # Use MCP
    try:
        result = client.mcp_query(
            query="What is the weather?",
            context={"user_id": "user123"}
        )
        print(f"MCP Result: {result}")
    except Exception as e:
        print(f"Error: {e}")
    
    # Use A2A
    try:
        result = client.a2a_send_message(
            message="Hello from agent A",
            target_agent="agent_b"
        )
        print(f"A2A Result: {result}")
    except Exception as e:
        print(f"Error: {e}")
    
    # Use MQTT
    try:
        result = client.mqtt_publish(
            topic="sensors/temperature",
            payload={"value": 25.5, "unit": "celsius"},
            qos=1
        )
        print(f"MQTT Published: {result}")
    except Exception as e:
        print(f"Error: {e}")


